function approveForAccounting(invoice,match,{approvedBy,exceptions=[]}={}){assert(match&&match.invoiceId===invoice.id,'Rapprochement de facture requis.');assert(match.blockingIssues.length===0,'La facture contient des anomalies bloquantes.');const who=text(approvedBy);assert(who,'Identité requise pour approuver la facture.');const accepted=new Map((exceptions||[]).map(x=>[text(x.issueId),text(x.reason)]));for(const r of match.reviewIssues){assert(accepted.has(r.id)&&accepted.get(r.id),`Exception explicite requise pour ${r.id}.`)}const next=clone(invoice);next.status='approved_for_accounting';next.review={approvedBy:who,approvedAt:now(),matchSnapshot:clone(match),exceptions:(exceptions||[]).map(clone),paymentStatus:'not-managed-by-this-module'};next.updatedAt=next.review.approvedAt;return next}
